import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Approvals and Trust","description":"","frontmatter":{},"headers":[],"relativePath":"guides/approvals.md","filePath":"guides/approvals.md","lastUpdated":1790952322000}'),n={name:"guides/approvals.md"};function r(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="approvals-and-trust" tabindex="-1">Approvals and Trust <a class="header-anchor" href="#approvals-and-trust" aria-label="Permalink to &quot;Approvals and Trust&quot;">​</a></h1><p>A bot that can write files, run commands, and message people needs a boundary you actually understand. This page explains that boundary from the user&#39;s side: what a bot can reach, when it stops to ask, and what approval does and does not cover. The mechanics — member lists, modes, and rules — live in <a href="./access.html">Access Control</a>.</p><h2 id="what-a-bot-can-touch-by-default" tabindex="-1">What a bot can touch by default <a class="header-anchor" href="#what-a-bot-can-touch-by-default" aria-label="Permalink to &quot;What a bot can touch by default&quot;">​</a></h2><ul><li><strong>Its own workspace, and nothing else.</strong> Each bot works inside its own isolated container workspace (<code>/data</code>). Files and state stay there, and bots cannot see into each other — see <a href="./container.html">Workspace</a>.</li><li><strong>Only the channels and people you connected.</strong> A bot reaches a platform because you added it on the <strong>Platforms</strong> tab, and answers an identity because access allows it.</li><li><strong>Only the tier each person was granted.</strong> Workspace access is tiered (chat, read files, write files, execute commands, manage), and a job gets the level it needs, no more. The tiers are defined in <a href="./access.html">Access Control</a>.</li></ul><p>Two member lists feed these grants, both on the bot&#39;s <strong>Access</strong> tab: <strong>Channel Members</strong> for identities on IM platforms, and <strong>Workspace Members</strong> for registered Memoh users.</p><h2 id="when-it-asks-you" tabindex="-1">When it asks you <a class="header-anchor" href="#when-it-asks-you" aria-label="Permalink to &quot;When it asks you&quot;">​</a></h2><p>Write and execute tool calls can require human approval, controlled per bot on its <strong>Tool Approval</strong> tab. When a tool is set to require confirmation, the flow is:</p><ol><li>The bot proposes the action — the specific tool call, before anything runs.</li><li>You approve or reject it.</li><li>Only an approved call executes; a rejected one never runs.</li></ol><p>Approval always happens before the action, so reviewing the request is your moment of control, not damage control. A pending request can also time out rather than wait forever; if you missed one, ask the bot to try the action again.</p><div class="tip custom-block"><p class="custom-block-title">More gates, if you want them</p><p>Beyond the Tool Approval settings, a <a href="./hooks.html">hook</a> matched on an event can itself request human approval — useful for guarding one specific command pattern rather than a whole tool.</p></div><h2 id="keep-these-behind-approval" tabindex="-1">Keep these behind approval <a class="header-anchor" href="#keep-these-behind-approval" aria-label="Permalink to &quot;Keep these behind approval&quot;">​</a></h2><p>These are recommendations, not defaults Memoh enforces; treat them as a sensible starting point:</p><ul><li><strong>Messages that leave the workspace</strong> — anything sent to other people or posted publicly.</li><li><strong>Deleting or overwriting files</strong>, especially ones the bot did not create.</li><li><strong>Installs and long-running commands</strong> in the workspace.</li><li><strong>Anything that spends money or touches production.</strong></li></ul><p>Actions that stay inside the bot&#39;s own workspace (drafting, organizing, reading) are the ones worth freeing from approval first. For how this fits a routine&#39;s lifecycle, from the first read-only run to widened permissions, see <a href="./working-with-bots.html">Working with Bots</a>.</p><h2 id="takeover-and-credentials" tabindex="-1">Takeover and credentials <a class="header-anchor" href="#takeover-and-credentials" aria-label="Permalink to &quot;Takeover and credentials&quot;">​</a></h2><p>When a bot working in its visible desktop hits a login wall or a CAPTCHA, you take over the screen and type the password, passkey, or one-time code yourself, then hand control back. The credential goes from your keyboard into the site — you never have to tell it to the bot.</p><p>The browser session stays in that workspace afterwards, so later tasks remain signed in without repeating the takeover. See <a href="./browser-computer-use.html">Browser / Computer Use</a> and <a href="./quick-start.html#step-5-let-it-use-the-workspace-and-browser">Quick Start</a>.</p><h2 id="an-honest-boundary-note" tabindex="-1">An honest boundary note <a class="header-anchor" href="#an-honest-boundary-note" aria-label="Permalink to &quot;An honest boundary note&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">What approval does not do</p><p>An approval gates the proposed action — it does not undo work that already ran, and it cannot retract a message that was already sent. Rejecting a request stops that request; it is not a rollback button.</p></div><p>That is why the durable habit is the one from <a href="./access.html">Access Control</a>: grant the minimum tier the job needs, review a few runs, and widen afterwards. Trust in a bot is built the same way as trust in a new teammate: incrementally, on evidence.</p>',20)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
